import json
import os
import shutil


def layout(path):
    # The table's data files from the log: how many, the lines in all, and the most and fewest lines in one file.
    # Don't change this.
    files = {}
    log = path + "/_delta_log/"
    for name in sorted(f for f in os.listdir(log) if f.endswith(".json")):
        with open(log + name) as f:
            for line in f:
                action = json.loads(line)
                if "add" in action:
                    files[action["add"]["path"]] = json.loads(action["add"]["stats"])["numRecords"]
                if "remove" in action:
                    files.pop(action["remove"]["path"], None)
    sizes = list(files.values()) or [0]
    return spark.createDataFrame(
        [(len(files), sum(sizes), max(sizes), min(sizes))],
        "files INT, lines INT, largest INT, smallest INT",
    )


def write_export(invoice_lines, path):
    # Three files of about the same size.
    invoice_lines.write.format("delta").save(path)


def solve(invoice_lines):
    path = "/tmp/erp/export"
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    write_export(invoice_lines, path)
    return layout(path)
